function lucide_icon(string $name, string $class = '', string $style = ''): string {
    global $LUCIDE_ICONS;
    $svg = $LUCIDE_ICONS[$name] ?? '';
    if ($svg === '') return '';
    if ($class !== '') {
        $svg = str_replace('class="lucide ', 'class="' . htmlspecialchars($class) . ' lucide ', $svg);
    }
    if ($style !== '') {
        $svg = preg_replace('/^<svg /', '<svg style="' . htmlspecialchars($style) . '" ', $svg);
    }
    return $svg;
}
